SELECT * FROM( SELECT D.RANK AS RK, D.* FROM( SELECT DENSE_RANK() OVER (ORDER BY A.INS_DT DESC, A.PROD_NO DESC) RANK , A.PROD_NO , A.PROD_NM , A.PRICE , A.DISCOUNT_RATE , A.SALE_PRICE , A.PROD_DESC , A.PROD_DETAIL_CONTENT , A.INS_DT , A.UPT_DT , A.USE_YN , B.CATEGORY_NM , C.BRAND_NM FROM TBL_PRODUCT A INNER JOIN TBL_CATEGORY B ON A.CATEGORY_NO = B.CATEGORY_NO INNER JOIN TBL_BRAND C ON A.BRAND_CD = C.BRAND_CD WHERE 1 = 1
) D
WHERE D.RANK <= #{ currentPageNo } * #{ recordsPerPage } )E WHERE E.RK > (#{ currentPageNo } - 1) * #{ recordsPerPage }

SELECT * FROM( SELECT D.RANK AS RK, D.* FROM( SELECT DENSE_RANK() OVER (ORDER BY A.INS_DT DESC, A.PROD_NO DESC) RANK , A.PROD_NM , A.PRICE , A.DISCOUNT_RATE , A.SALE_PRICE , A.PROD_DESC , A.PROD_DETAIL_CONTENT , A.INS_DT , A.UPT_DT , A.USE_YN , B.CATEGORY_NM , C.BRAND_NM FROM TBL_PRODUCT A INNER JOIN TBL_CATEGORY B ON A.CATEGORY_NO = B.CATEGORY_NO INNER JOIN TBL_BRAND C ON A.BRAND_CD = C.BRAND_CD WHERE A.USE_YN = 'Y'
) D
WHERE D.RANK <= #{ currentPageNo } * #{ recordsPerPage } )E WHERE E.RK > (#{ currentPageNo } - 1) * #{ recordsPerPage }

mapper.insert:
INSERT
INTO TBL_PRODUCT
(
PROD_NO
,PROD_NM
,BRAND_CD
,CATEGORY_NO
,PRICE
,DISCOUNT_RATE
,SALE_PRICE
,PROD_DESC
,PROD_DETAIL_CONTENT
,INS_DT
,UPT_DT
,USE_YN
)
VALUES
(
SEQ_PROD_NO.NEXTVAL
, #{ prodNm }
, #{ brandCd }
, #{ categoryNo }
, #{ price }
, #{ discountRate }
, #{ salePrice }
, #{ prodDesc }
, #{ prodDetailContent }
, SYSDATE
, SYSDATE
, DEFAULT
)


